const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Implements the Source/Lease contract in src/source.ts.
function fixture({ values = ['a', 'b', null], readError, closeError, mapper } = {}) {
  const calls = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      calls.opens++;
      return {
        async read() {
          calls.reads++;
          if (readError) throw readError;
          return values.shift();
        },
        async close() {
          calls.closes++;
          if (closeError) throw closeError;
        },
      };
    },
  };
  return { calls, service: new EventService(source, mapper) };
}

async function main() {
  {
    const { service, calls } = fixture();
    const unopened = service.stream();
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
    await unopened.return();
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
    const stream = service.stream();
    assert.deepEqual(await stream.next(), { value: 'A', done: false });
    assert.deepEqual(calls, { opens: 1, reads: 1, closes: 0 });
    assert.deepEqual(await stream.next(), { value: 'B', done: false });
    assert.equal(calls.reads, 2);
    assert.equal(calls.closes, 0);
    assert.deepEqual(await stream.next(), { value: undefined, done: true });
    await stream.next();
    await stream.return();
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
  }
  for (const closeError of [undefined, new Error('close')]) {
    for (const exit of ['exhaustion', 'break', 'return']) {
      const { service, calls } = fixture({ closeError });
      const consume = async () => {
        if (exit === 'return') {
          const stream = service.stream();
          await stream.next();
          await stream.return();
          await stream.return();
        } else {
          const found = [];
          for await (const value of service.stream()) {
            found.push(value);
            if (exit === 'break') break;
          }
          assert.deepEqual(found, exit === 'break' ? ['A'] : ['A', 'B']);
        }
      };
      if (closeError) await assert.rejects(consume(), error => error === closeError);
      else await consume();
      assert.deepEqual(calls, { opens: 1, reads: exit === 'exhaustion' ? 3 : 1, closes: 1 });
    }
    for (const failure of ['read', 'mapper', 'throw']) {
      // Include undefined to ensure error precedence is not based on truthiness.
      for (const original of [new Error(failure), undefined]) {
        const { service, calls } = fixture({
          closeError,
          mapper: failure === 'mapper' ? () => { throw original; } : undefined,
        });
        const stream = service.stream();
        // For read failures, use a Source whose read rejects with the exact value.
        const target = failure === 'read'
          ? new EventService({ async open() {
              calls.opens++;
              return {
                async read() { calls.reads++; throw original; },
                async close() { calls.closes++; if (closeError) throw closeError; },
              };
            } }).stream()
          : stream;
        if (failure === 'throw') await target.next();
        await assert.rejects(
          failure === 'throw' ? target.throw(original) : target.next(),
          error => error === original,
        );
        await target.next();
        await target.return();
        assert.deepEqual(calls, { opens: 1, reads: 1, closes: 1 });
      }
    }
  }
  {
    const original = new Error('open');
    const service = new EventService({ async open() { throw original; } });
    await assert.rejects(service.stream().next(), error => error === original);
  }
}
module.exports = main();

